package alphametics

import (
	"fmt"
	"strings"
	"unicode"
)

// letterCount is a letter occurring in one column of a puzzle together with
// the number of times it occurs in that column.
type letterCount struct {
	letter rune
	count  int
}

// column is one decimal position of a puzzle, least significant first.
type column struct {
	addends  []letterCount // distinct letters of the addends, with counts
	result   rune          // letter of the result word in this column, 0 if shorter
	resultCount int        // how often the result letter occurs among the addends
}

// Solve solves an alphametics puzzle of the form "WORD + WORD + ... == WORD".
// It returns a mapping of each letter to a distinct digit that makes the
// equation true, or an error if the puzzle has no solution.
func Solve(puzzle string) (map[string]int, error) {
	addends, result, err := parse(puzzle)
	if err != nil {
		return nil, err
	}

	leading := make(map[rune]bool)
	letterSet := make(map[rune]bool)
	for _, word := range append(append([]string{}, addends...), result) {
		rs := []rune(word)
		for _, r := range rs {
			letterSet[r] = true
		}
		if len(rs) > 1 {
			leading[rs[0]] = true
		}
	}
	if len(letterSet) > 10 {
		return nil, fmt.Errorf("puzzle has %d distinct letters, but only 10 digits exist", len(letterSet))
	}

	columns := buildColumns(addends, result)

	value := make(map[rune]int, len(letterSet))
	used := [10]bool{}

	// solve checks columns from least to most significant, carrying the
	// overflow between them.
	var solve func(col, carry int) bool
	solve = func(col, carry int) bool {
		if col == len(columns) {
			return carry == 0
		}
		c := columns[col]

		// Fold the already assigned addend letters into the running sum
		// and collect the ones that still need a digit.
		sum := carry
		var unassigned []letterCount
		for _, lc := range c.addends {
			if v, ok := value[lc.letter]; ok {
				sum += lc.count * v
			} else {
				unassigned = append(unassigned, lc)
			}
		}

		// If the result letter is unassigned and also occurs among the
		// addends of this column, its digit is not free: it is determined
		// by the column equation, so it is assigned after the others.
		determined := false
		if c.result != 0 {
			if _, ok := value[c.result]; !ok {
				for i, lc := range unassigned {
					if lc.letter == c.result {
						unassigned = append(unassigned[:i], unassigned[i+1:]...)
						determined = true
						break
					}
				}
			}
		}

		var assign func(idx, sum int) bool
		assign = func(idx, sum int) bool {
			if idx == len(unassigned) {
				// The column equation must hold: the total's units digit
				// must equal the result letter's digit.
				if c.result != 0 {
					if v, ok := value[c.result]; ok {
						if sum%10 != v {
							return false
						}
					} else if determined {
						// The result letter contributes c.resultCount
						// times to the total, so its digit d must
						// satisfy (sum + c.resultCount*d) % 10 == d.
						for d := 0; d <= 9; d++ {
							if (sum+c.resultCount*d)%10 != d ||
								used[d] || (leading[c.result] && d == 0) {
								continue
							}
							value[c.result] = d
							used[d] = true
							ok := solve(col+1, (sum+c.resultCount*d)/10)
							delete(value, c.result)
							used[d] = false
							if ok {
								return true
							}
						}
						return false
					} else {
						d := sum % 10
						if used[d] || (leading[c.result] && d == 0) {
							return false
						}
						value[c.result] = d
						used[d] = true
						ok := solve(col+1, sum/10)
						delete(value, c.result)
						used[d] = false
						return ok
					}
				} else if sum%10 != 0 {
					// The result word is shorter than this column, so the
					// column must contribute nothing to it.
					return false
				}
				return solve(col+1, sum/10)
			}

			lc := unassigned[idx]
			for d := 0; d <= 9; d++ {
				if used[d] || (leading[lc.letter] && d == 0) {
					continue
				}
				value[lc.letter] = d
				used[d] = true
				if assign(idx+1, sum+lc.count*d) {
					return true
				}
				delete(value, lc.letter)
				used[d] = false
			}
			return false
		}

		return assign(0, sum)
	}

	if !solve(0, 0) {
		return nil, fmt.Errorf("no solution for puzzle %q", puzzle)
	}

	out := make(map[string]int, len(value))
	for r, d := range value {
		out[string(r)] = d
	}
	return out, nil
}

// parse splits a puzzle into its addend words and its result word.
func parse(puzzle string) ([]string, string, error) {
	parts := strings.Split(puzzle, "==")
	if len(parts) != 2 {
		return nil, "", fmt.Errorf("invalid puzzle %q: expected exactly one '=='", puzzle)
	}
	addends := strings.FieldsFunc(parts[0], func(r rune) bool { return r == '+' })
	for i, w := range addends {
		addends[i] = strings.TrimSpace(w)
	}
	result := strings.TrimSpace(parts[1])
	if err := validateWords(append(append([]string{}, addends...), result)...); err != nil {
		return nil, "", err
	}
	return addends, result, nil
}

// validateWords reports an error if any word is empty or contains a
// non-letter character.
func validateWords(words ...string) error {
	for _, w := range words {
		if w == "" {
			return fmt.Errorf("invalid puzzle: empty word")
		}
		for _, r := range w {
			if !unicode.IsLetter(r) {
				return fmt.Errorf("invalid puzzle: word %q contains non-letter %q", w, r)
			}
		}
	}
	return nil
}

// buildColumns lays the words out by decimal position, least significant
// first, deduplicating repeated letters within a column.
func buildColumns(addends []string, result string) []column {
	maxLen := len([]rune(result))
	for _, w := range addends {
		if l := len([]rune(w)); l > maxLen {
			maxLen = l
		}
	}
	columns := make([]column, maxLen)
	for c := 0; c < maxLen; c++ {
		for _, w := range addends {
			rs := []rune(w)
			pos := len(rs) - 1 - c
			if pos < 0 {
				continue
			}
			addToColumn(&columns[c], rs[pos])
		}
		rrs := []rune(result)
		if pos := len(rrs) - 1 - c; pos >= 0 {
			columns[c].result = rrs[pos]
			for _, lc := range columns[c].addends {
				if lc.letter == columns[c].result {
					columns[c].resultCount = lc.count
				}
			}
		}
	}
	return columns
}

// addToColumn adds a letter to a column, incrementing the count if the
// letter is already present.
func addToColumn(col *column, letter rune) {
	for i := range col.addends {
		if col.addends[i].letter == letter {
			col.addends[i].count++
			return
		}
	}
	col.addends = append(col.addends, letterCount{letter: letter, count: 1})
}

